/**
 * A measured value in a known range (`design/components/meter.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/meter.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { Icon, claimSlot, createDerived, scope, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/meter.module.css'

export interface MeterMessages {
  /** The glyph's name past `warning`: "High". */
  warning: string
  /** The glyph's name past `danger`: "Critical". */
  danger: string
}

export interface MeterProps {
  /**
   * From this value up, the meter is in its danger band.
   */
  danger?: number
  /**
   * Required, because an unnamed meter tells a screen reader nothing.
   */
  label: string
  /**
   * The top of the range: the limit, the quota, the budget.
   */
  max?: number
  /**
   * The status glyph's names. English when omitted.
   */
  messages?: MeterMessages
  /**
   * The bottom of the range.
   */
  min?: number
  /**
   * The measured value, in the range's units. It is drawn clamped to `min`–`max`.
   */
  value: number
  /**
   * The value in the app's words, seen under the bar and heard as the meter's value.
   */
  valueText?: string
  /**
   * From this value up, the meter is in its warning band.
   */
  warning?: number
}

/** A measured value in a known range. */
export default function Meter(given: MeterProps): JSX.Element {
  const props = mergeProps(
    { min: 0, max: 100, messages: (() => ({ warning: 'High', danger: 'Critical' }))() } as Defaults<
      MeterProps,
      'min' | 'max' | 'messages'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const shown = createDerived(() => Math.min(props.max, Math.max(props.min, props.value)))
    const ratio = createDerived(() =>
      props.max > props.min ? (shown.value - props.min) / (props.max - props.min) : 0,
    )
    const tone = createDerived(() =>
      props.danger !== undefined && props.value >= props.danger
        ? 'danger'
        : props.warning !== undefined && props.value >= props.warning
          ? 'warning'
          : 'accent',
    )
    return (
      <div class={styles.meter} data-tone={tone.value} data-member="meter">
        {/* track */}
        <div
          class={styles.track}
          role="meter"
          aria-label={props.label}
          aria-valuenow={shown.value}
          aria-valuemin={props.min}
          aria-valuemax={props.max}
          aria-valuetext={props.valueText}
        >
          {/* fill */}
          <div class={styles.fill} style={{ transform: `scaleX(${ratio.value})` }} />
        </div>
        {tone.value !== 'accent' || props.valueText !== undefined ? (
          <div class={styles.readout}>
            {tone.value !== 'accent' ? (
              <span class={styles.status}>
                <Icon
                  name={tone.value === 'danger' ? 'error' : 'warning'}
                  size="sm"
                  label={tone.value === 'danger' ? props.messages.danger : props.messages.warning}
                />
              </span>
            ) : null}
            {props.valueText !== undefined ? (
              <span class={styles.value} aria-hidden="true">
                {props.valueText}
              </span>
            ) : null}
          </div>
        ) : null}
      </div>
    )
  })
}
